S=/workspace/nox/web/site; cd $S
export PATH=/workspace/nox/tools/node/bin:$PATH
echo '' | base64 -d | gunzip > nox-chat-x.css
echo '' | base64 -d | gunzip > nox-chat-x.js
mkdir -p vendor/nox-lib/highlightjs; rm -rf /tmp/w3hl; mkdir /tmp/w3hl; cd /tmp/w3hl; npm pack @highlightjs/cdn-assets@11 2>&1 | tail -1; tar xzf *.tgz
ls package package/es | head -20
cp package/es/highlight.min.js $S/vendor/nox-lib/highlightjs/highlight.min.mjs; cp package/LICENSE $S/vendor/nox-lib/highlightjs/LICENSE 2>/dev/null
cd $S; [ -f chat.html.bak_w3_1 ] || cp chat.html chat.html.bak_w3_1
python3 - <<'P'
p='/workspace/nox/web/site/chat.html'; s=open(p,encoding='utf-8').read()
if 'nox-chat-x' not in s:
    s=s.replace('</head>','<script>try{localStorage.setItem("nox.wow.tour","1")}catch(e){}</script>\n<link rel="stylesheet" href="./nox-chat-x.css?v=1">\n</head>',1)
    s=s.replace('</body>','<script type="module" src="./nox-chat-x.js?v=1"></script>\n</body>',1)
    open(p,'w',encoding='utf-8').write(s); print('patched')
P
head -c 300 vendor/nox-lib/highlightjs/highlight.min.mjs; echo; grep -c "export" vendor/nox-lib/highlightjs/highlight.min.mjs; tail -c 200 vendor/nox-lib/highlightjs/highlight.min.mjs
